if (pal) {
  const center = pal.pos, offset = new THREE.Vector2(rnd() - .5, rnd() - .5).multiplyScalar(2.5);
  let p = center.clone().add(offset); // Original target is the fallback; draw count is unchanged.
  if (this.kind === "cow" && pal.kind === "cow" && pen === pal.pen && pen && weather === "fair" && !PRESET.night && !this.cowTask) {
    const near = this.pos.sub(center);
    if (near.lengthSq() > .01) {
      near.normalize();
      const flank = new THREE.Vector2(-near.y, near.x);
      const side = offset.dot(flank) < 0 ? -1 : 1;
      const lateral = 1.1 + Math.min(.45, offset.length() * .3);
      for (const sign of [side, -side]) {
        const q = center.clone().addScaledVector(near, .45).addScaledVector(flank, sign * lateral);
        if (inPen(pen, q.x, q.y, roamClearance) && !BLOCKS.some(([bx,bz,hw,hd]) => Math.abs(q.x-bx)<hw+roamClearance && Math.abs(q.y-bz)<hd+roamClearance)) { p = q; break; }
      }
    }
  }
  this.friend = pal; return this.go(p.x, p.y, false, "Visiting " + pal.name, "social");
}
